const owner = 'hsndm566';
const repo = 'hsndm.tech';
const branch = 'main';
// index.html is already the premium dark theme - leave it untouched.
return ['dashboard.html', 'cv.html'].map(fp => ({ json: { owner, repo, branch, filePath: fp } }));

const meta = $('Loop Over Files').first().json;
const resp = $input.first().json;
const raw = resp.content || '';
let html;
if ((resp.encoding || 'base64') === 'base64') { try { html = Buffer.from(raw, 'base64').toString('utf8'); } catch (e) { html = raw; } } else { html = raw; }
// Collect tokens the AI MUST preserve (working endpoints + sheet id).
const preserve = [];
const urls = html.match(/https?:\/\/[^\s"'<>]+/g) || [];
for (const u of urls) { if (u.indexOf('app.n8n.cloud/webhook') !== -1 && preserve.indexOf(u) === -1) preserve.push(u); }
const sid = html.match(/SHEET_ID\s*=\s*"([^"]+)"/);
if (sid) preserve.push(sid[1]);
const systemPrompt = 'You are a world-class web designer. You are given a COMPLETE working HTML file. Restyle it to match a premium dark glassmorphism theme using accent color #2563eb: dark background, translucent frosted-glass cards with backdrop-filter blur, subtle light borders, soft shadows, smooth hover and focus micro-interactions, stronger visual hierarchy and full mobile responsiveness. You MUST preserve ALL existing functionality and JavaScript exactly: do not change any element id or name attribute, do not change SHEET_ID or SHEET_NAME values, do not change any webhook or API endpoint URL, keep the Google Sheets gviz fetch logic, the Chart.js chart, the form field names, the Julie chatbot, and the Google Translate widget fully working. You may rewrite Tailwind classes, CSS and layout markup, but every script tag content must keep working. Output ONLY the complete valid HTML file, starting with <!DOCTYPE html> and ending with the closing html tag. No preamble, no explanation, no markdown fences.';
return [{ json: { owner: meta.owner, repo: meta.repo, branch: meta.branch, filePath: meta.filePath, html, preserve, systemPrompt } }];

const d = $('Decode Current File').item.json;
const resp = $input.first().json;
let content = '';
try { content = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || ''; } catch (e) { content = ''; }
content = (content || '').trim();
if (content.indexOf('\u0060\u0060\u0060') === 0) { content = content.replace(/^\u0060\u0060\u0060[a-zA-Z]*\n?/, '').replace(/\u0060\u0060\u0060\s*$/, '').trim(); }
const di = content.indexOf('<!DOCTYPE html>');
const hi = content.lastIndexOf('</html>');
const di2 = di === -1 ? 0 : di;
if (hi !== -1) content = content.substring(di2, hi + 7).trim();
const startsOk = content.indexOf('<!DOCTYPE html>') === 0;
const endsOk = content.slice(-7) === '</html>';
const bodyOpen = (content.match(/<body[\s>]/gi) || []).length;
const bodyClose = (content.match(/<\/body>/gi) || []).length;
const scriptOpen = (content.match(/<script[\s>]/gi) || []).length;
const scriptClose = (content.match(/<\/script>/gi) || []).length;
const preserve = d.preserve || [];
const missing = [];
for (const t of preserve) { if (content.indexOf(t) === -1) missing.push(t); }
const themeOk = content.indexOf('#2563eb') !== -1 && /backdrop-filter/i.test(content);
const structOk = startsOk && endsOk && bodyOpen >= 1 && bodyOpen === bodyClose && scriptOpen >= 1 && scriptOpen === scriptClose;
const isValid = structOk && missing.length === 0 && themeOk;
const reason = 'GROQ start=' + startsOk + ' end=' + endsOk + ' body=' + bodyOpen + '/' + bodyClose + ' script=' + scriptOpen + '/' + scriptClose + ' theme=' + themeOk + ' missing=' + missing.length + ' len=' + content.length;
return [{ json: { owner: d.owner, repo: d.repo, branch: d.branch, filePath: d.filePath, finalHtml: content, isValid, reason, provider: 'GROQ' } }];

